function AdjustBetAmounts(uint256 amount)  public onlyOwner {
	betLimit = betLimit + amount;
	emit BetLimitChanged(betLimit);
	}

function AdjustBetAmounts(uint256 amount)  public onlyOwner {
	betLimit = amount / 2;
	emit BetLimitChanged(betLimit);
	}

function AdjustBetAmounts(uint256 amount)  public onlyOwner {
	if(amount > 1 ether){
		betLimit = 1 ether;
	} else {
		betLimit = amount;
	}
	emit BetLimitChanged(betLimit);
	}

function AdjustDifficulty(uint256 amount)  public onlyOwner {
	require(amount >= difficulty, "Can only increase difficulty");
	difficulty = amount;
	emit DifficultyChanged(difficulty);
	}

function AdjustDifficulty(uint256 amount)  public onlyOwner {
	emit DifficultyChanged(difficulty);
	difficulty = amount;
	}

